/**
 * Unit tests for DeserializationContext#instantiationException.
 */
public class DeserializationContext_instantiationException_TriageGen0Test {

    @Mock
    private DeserializerFactory _deserializerFactory;

    @Mock
    private JsonParser _parser;

    private DeserializationContext _context;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        // DeserializationContext has protected constructors. 
        // We use the one with DeserializerFactory.
        _context = new DeserializationContext(_deserializerFactory);

        // The method uses a private field '_parser'. We need to inject the mock parser via reflection 
        // because instantiationException calls InvalidDefinitionException.from(_parser, ...)
        Field parserField = DeserializationContext.class.getDeclaredField("_parser");
        parserField.setAccessible(true);
        parserField.set(_context, _parser);
    }

    @Test
    public void testInstantiationException_WithNullCause() {
        Class<?> targetClass = String.class;

        JsonMappingException exception = _context.instantiationException(targetClass, null);

        assertNotNull(exception);
        assertTrue(exception instanceof InvalidDefinitionException);
        // If cause is null, msg should contain "problem: N/A"
        assertTrue(exception.getMessage().contains("problem: N/A"));
        assertTrue(exception.getMessage().contains("java.lang.String"));
    }

    @Test
    public void testInstantiationException_WithCauseHavingMessage() {
        Class<?> targetClass = Integer.class;
        String errorMessage = "Specific error message";
        RuntimeException cause = new RuntimeException(errorMessage);

        JsonMappingException exception = _context.instantiationException(targetClass, cause);

        assertNotNull(exception);
        assertTrue(exception.getMessage().contains("problem: " + errorMessage));
        assertEquals(cause, exception.getCause());
    }

    @Test
    public void testInstantiationException_WithCauseHavingNullMessage() {
        Class<?> targetClass = Double.class;
        // Create a Throwable where getMessage() returns null
        Throwable cause = new Throwable((String) null);

        JsonMappingException exception = _context.instantiationException(targetClass, cause);

        assertNotNull(exception);
        // If cause.getMessage() is null, it should use ClassUtil.nameOf(cause.getClass())
        // For a plain Throwable, it should be "java.lang.Throwable"
        assertTrue(exception.getMessage().contains("problem: java.lang.Throwable"));
        assertEquals(cause, exception.getCause());
    }

    @Test
    public void testInstantiationException_ComplexType() {
        // Testing with a custom class to ensure constructType and ClassUtil work as expected
        class MyTestClass {}

        JsonMappingException exception = _context.instantiationException(MyTestClass.class, null);

        assertNotNull(exception);
        assertTrue(exception.getMessage().contains("Cannot construct instance of MyTestClass"));
    }
}
